function migrate(s){if(!s||!Array.isArray(s.tasks)||!Array.isArray(s.rewards)||!Array.isArray(s.ledger)||!Array.isArray(s.history))throw Error('Érvénytelen mentés');s.tasks=s.tasks.map(t=>({...t,category:t.category||'Egyéb',weekdays:Array.isArray(t.weekdays)?t.weekdays:[0,1,2,3,4,5,6],weeklyTarget:Math.min(7,Math.max(1,Number(t.weeklyTarget)||1)),subtasks:Array.isArray(t.subtasks)?t.subtasks:[],paused:Array.isArray(t.paused)?t.paused:[],days:Array.isArray(t.days)?t.days:[]}));s.settings={reminder:'20:00',reminderEnabled:false,...s.settings};s.focusSessions=Array.isArray(s.focusSessions)?s.focusSessions:[];s.questClaims=Array.isArray(s.questClaims)?s.questClaims:[];s.subtaskChecks=s.subtaskChecks||{};s.wishId=s.wishId||null;s.tasks.forEach(t=>{t.priority=['low','medium','high'].includes(t.priority)?t.priority:'medium'});s.tasks.forEach(t=>{if(t.kind==='todo')t.dueDate=t.dueDate||t.created||day()});s.categories=Array.isArray(s.categories)&&s.categories.length?s.categories:['Munka','Otthon','Egészség','Tanulás','Egyéb'];s.progressLogs=Array.isArray(s.progressLogs)?s.progressLogs:[];s.activeRewards=Array.isArray(s.activeRewards)?s.activeRewards:[];s.weeklyChallenges=Array.isArray(s.weeklyChallenges)?s.weeklyChallenges:[];s.settings.dailyXPGoal=Math.max(1,Number(s.settings.dailyXPGoal)||100);s.ui=s.ui||{blocks:['level','progress','tasks','quests','wish'],hidden:[]};s.ui.blocks=Array.isArray(s.ui.blocks)?s.ui.blocks:['level','progress','tasks','quests','wish'];s.ui.hidden=Array.isArray(s.ui.hidden)?s.ui.hidden:[];s.tasks.forEach(t=>{t.order=Number.isFinite(t.order)?t.order:0;t.goal=t.goal||null});s.rewards.forEach(r=>r.minutes=Number(r.minutes)||0);s.version=7;return s}
try{
 originalSave=localStorage.getItem(KEY);
 state=migrate(originalSave===null?seed():JSON.parse(originalSave));
}catch{
 recoveryRequired=true;
 state=migrate(seed());
}
// Never overwrite an unreadable save with demo data, including on later actions.
function replaceState(incoming){
 try{localStorage.setItem(KEY,JSON.stringify(incoming))}catch{toast('Mentés sikertelen – a korábbi adatok változatlanok.');return false}
 state=incoming;recoveryRequired=false;originalSave=null;return true;
}
function recoveryHTML(){return `<div class="card" role="alert"><h2>A mentés nem tölthető be</h2><p>A korábbi adataidat nem írtuk felül. Töltsd le az eredeti mentést, vagy importálj egy működő biztonsági mentést.</p><div class="actions"><button class="btn" data-action="export" ${originalSave===null?'disabled':''}>Eredeti mentés letöltése</button><button class="btn alt" data-action="import">JSON import</button><button class="btn danger" data-action="reset">Újrakezdés</button></div><input type="file" id="importFile" accept=".json,application/json" class="hidden"></div>`}

const save=()=>{if(recoveryRequired)return false;try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Mentés sikertelen – exportálj biztonsági mentést!');return false}};
const wallet=()=>state.ledger.reduce((n,x)=>n+Number(x.amount||0),0),xp=()=>state.history.filter(h=>h.type==='task'||h.type==='quest'||h.type==='focus'||h.type==='challenge').reduce((n,h)=>n+Number(h.points||0),0),level=()=>Math.floor(xp()/200)+1;
const isDone=(t,d=day())=>t.kind==='todo'?t.days.length>0&&(t.dueDate||t.created)===d:t.days.includes(d),isPaused=(t,d=day())=>t.paused.includes(d),weeklyCount=(t,d=day())=>t.days.filter(x=>x>=weekStart(d)&&x<=shift(weekStart(d),6)).length;
function scheduled(t,d=day()){if(t.created>d||isPaused(t,d))return false;if(t.kind==='todo')return (t.dueDate||t.created)===d;if(t.frequency==='weekdays')return t.weekdays.includes(weekday(d));if(t.frequency==='weekly')return weeklyCount(t,d)<t.weeklyTarget||isDone(t,d);return true}
const completeToday=()=>state.history.filter(h=>h.type==='task'&&h.date===day()),completedOn=d=>state.history.filter(h=>h.type==='task'&&h.date===d),pointsOn=d=>state.history.filter(h=>h.date===d&&(h.type==='task'||h.type==='quest'||h.type==='focus'||h.type==='challenge')).reduce((a,h)=>a+h.points,0);
function streak(t){if(t.kind!=='habit')return {current:0,best:0};let days=[...new Set(t.days)].sort(),best=0,run=0,prev='';for(const d of days){let scheduledBetween=0;if(prev){for(let x=shift(prev,1);x<d;x=shift(x,1)){if(scheduled(t,x))scheduledBetween++}}run=!prev||scheduledBetween===0?run+1:1;best=Math.max(best,run);prev=d}let current=0,check=day();if(!isDone(t,check))check=shift(check,-1);for(let n=0;n<400&&check>=t.created;n++,check=shift(check,-1)){if(isPaused(t,check)||!scheduled(t,check))continue;if(isDone(t,check))current++;else break}return {current,best}}
const achievements=()=>[{name:'Első lépés',desc:'1 teljesített feladat',icon:'🌱',ok:state.history.some(h=>h.type==='task')},{name:'Lendületben',desc:'10 teljesítés',icon:'⚡',ok:state.history.filter(h=>h.type==='task').length>=10},{name:'Százados',desc:'100 XP',icon:'💯',ok:xp()>=100},{name:'Jutalmazd magad',desc:'1 beváltás',icon:'🎁',ok:state.history.some(h=>h.type==='reward')},{name:'Kitartó',desc:'5. szint',icon:'🏆',ok:level()>=5},{name:'Sorozatmester',desc:'7-es szokássorozat',icon:'🔥',ok:state.tasks.some(t=>streak(t).best>=7)},{name:'Fókuszmester',desc:'5 fókuszblokk',icon:'⏱️',ok:state.focusSessions.length>=5}];
