// Curated GIPHY embeds: no API key or server required. Select by task name and category.
function celebrate(points,message='Küldetés teljesítve!'){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelector('.celebration')?.remove();const layer=document.createElement('div');layer.className='celebration';layer.setAttribute('aria-hidden','true');let pop=document.createElement('div');pop.className='reward-pop';pop.textContent=`+${points} XP ✨`;let small=document.createElement('small');small.textContent=message;pop.append(small);layer.append(pop);const colors=['#35bd85','#ffd166','#8da7ff','#ff8da1','#b4e8df'];for(let i=0;i<30;i++){let p=document.createElement('i');p.className='confetti';p.style.setProperty('--x',Math.random()*100+'%');p.style.setProperty('--c',colors[i%5]);p.style.setProperty('--delay',Math.random()*.25+'s');layer.append(p)}document.body.append(layer);setTimeout(()=>layer.remove(),1700)}
const CATEGORIES=['Munka','Otthon','Egészség','Tanulás','Egyéb'],CATEGORY_ICONS={'Munka':'💼','Otthon':'🏠','Egészség':'💚','Tanulás':'📚','Egyéb':'✨'},PRIORITY_ORDER={high:0,medium:1,low:2};
const EMOJIS=['✨','📚','🧹','🏃','🐶','💼','🏠','💚','🧠','💪','🚴','🧘','💧','🥗','🛏️','🧼','🧺','🛒','📝','📅','💻','📞','📖','🎯','🎨','🎮','🎴','🍿','🎁','☕','🎵','🌿','⭐','🔥','💰','🚀','🧑‍🍳','🍳','🚗','🧽','🪴','🐱','❤️','🏆'];
function sortedTasks(items){return [...items].sort((a,b)=>(PRIORITY_ORDER[a.priority]??1)-(PRIORITY_ORDER[b.priority]??1)||(a.order||0)-(b.order||0)||a.name.localeCompare(b.name,'hu'))}
function groupedTasks(items,fn,prefix='today'){return [...new Set([...state.categories,...items.map(t=>t.category)])].filter(c=>items.some(t=>t.category===c)).map(c=>{let group=items.filter(t=>t.category===c),key=prefix+':'+c,collapsed=collapsedGroups.has(key);return `<section class="category-group"><button class="category-heading category-toggle" data-action="collapse" data-group="${esc(key)}" aria-expanded="${!collapsed}"><span>${CATEGORY_ICONS[c]||'📌'} ${esc(c)}</span><span class="category-meta">${group.filter(t=>isDone(t,selectedDate)).length}/${group.length} <span>${collapsed?'⌄':'⌃'}</span></span></button>${collapsed?'':`<div class="card category-card">${sortedTasks(group).map(fn).join('')}</div>`}</section>`}).join('')}
function taskHTML(t){
 const d=selectedDate,done=isDone(t,d),priority=t.priority||'medium';
 const priorityText={high:'Fontos',medium:'Normál',low:'Ráérős'}[priority];
 return `<div class="item task-row ${done?'task-completed':''}"><button type="button" class="emoji emoji-edit" data-action="editTask" data-id="${esc(t.id)}" aria-label="${esc(t.name)} szerkesztése">${esc(t.emoji)}</button><div class="grow"><div class="name">${esc(t.name)}</div><div class="task-meta"><span class="priority-dot priority-dot-${esc(priority)}" title="${priorityText}" role="img" aria-label="${priorityText} prioritás"></span><span>${t.kind==='habit'?'Szokás':'Egyszeri teendő'}</span>${t.kind==='habit'?`<span class="task-streak">✦ ${streak(t).current} sorozat</span>`:''}</div>${t.goal?goalHTML(t):''}</div><span class="task-xp">+${t.points}<small>XP</small></span><button class="check ${done?'done':''}" data-action="toggle" data-id="${esc(t.id)}" aria-label="${done?'Visszavonás':'Teljesítés'}: ${esc(t.name)}" ${d>day()?'disabled title="Jövőbeli feladat nem teljesíthető"':''}>${done?'✓':'<span aria-hidden="true">✓</span>'}</button></div>`;
}
function dateStrip(){
 const first=weekStart(selectedDate),labels=['H','K','Sze','Cs','P','Szo','V'];
 return `<section class="week-calendar" aria-label="Heti naptár"><div class="week-heading"><span>${fromKey(selectedDate).toLocaleDateString('hu-HU',{year:'numeric',month:'long'})}</span><div>${selectedDate!==day()?'<button class="week-today" data-action="dateToday">Ma</button>':''}<button class="date-arrow" data-action="dateShift" data-offset="-7" aria-label="Előző hét">‹</button><button class="date-arrow" data-action="dateShift" data-offset="7" aria-label="Következő hét">›</button></div></div><div class="date-strip">${Array.from({length:7},(_,i)=>{const d=shift(first,i),date=fromKey(d),active=completedOn(d).length>0;return `<button class="date-day ${d===selectedDate?'active':''} ${d===day()?'is-today':''}" data-action="dateSelect" data-date="${d}" aria-pressed="${d===selectedDate}" aria-label="${date.toLocaleDateString('hu-HU',{month:'long',day:'numeric',weekday:'long'})}${active?', van teljesítés':''}"><span>${labels[i]}</span><strong>${date.getDate()}</strong><i class="day-activity ${active?'has-activity':''}" aria-hidden="true"></i></button>`}).join('')}</div></section>`;
}
function rewardHTML(r){return `<div class="item"><span class="emoji">${esc(r.emoji)}</span><div class="grow"><div class="name">${esc(r.name)}</div><div class="muted">${r.cost} XP ${state.wishId===r.id?'· 🎯 Célod':''}</div></div><button class="btn small" data-action="redeem" data-id="${esc(r.id)}" ${wallet()<r.cost?'disabled':''}>Beváltás</button></div>`}
function goalWindow(t,d=day()){const start=t.goal.period==='month'?d.slice(0,7)+'-01':weekStart(d);const end=t.goal.period==='month'?shift(dateKey(new Date(fromKey(start).getFullYear(),fromKey(start).getMonth()+1,1)),-1):shift(start,6);return [start,end]}
function goalValue(t){if(!t.goal)return 0;const [start,end]=goalWindow(t);return state.progressLogs.filter(x=>x.taskId===t.id&&x.date>=start&&x.date<=end).reduce((a,x)=>a+x.value,0)}
function goalHTML(t){let n=goalValue(t);return `<div class="goal-inline"><span>🎯 ${n}/${t.goal.target} ${esc(t.goal.unit)} (${t.goal.period==='week'?'heti':'havi'})</span><button class="btn small alt" data-action="goalAdd" data-id="${esc(t.id)}">+ Rögzítés</button></div><div class="progress"><div class="bar" style="width:${Math.min(100,n/t.goal.target*100)}%"></div></div>`}
function timerHTML(){return state.activeRewards.filter(r=>r.end>Date.now()).map(r=>`<div class="card">⏳ ${esc(r.name)} <strong data-timer="${esc(r.id)}">${fmtTime(Math.ceil((r.end-Date.now())/1000))}</strong></div>`).join('')}
function heatmap(){let cells='';for(let i=55;i>=0;i--){let d=shift(day(),-i),n=completedOn(d).length;cells+=`<div class="heatcell h${Math.min(n,4)}" title="${d}: ${n} teljesítés" aria-label="${d}: ${n} teljesítés"></div>`}return `<div class="heatmap" aria-label="Az elmúlt 56 nap aktivitása">${cells}</div><div class="muted">Elmúlt 8 hét · világos: kevesebb, sötét: több teljesítés</div>`}
function weeklySummary(){let start=weekStart(day()),days=Array.from({length:7},(_,i)=>shift(start,i)),counts=days.map(d=>completedOn(d).length),best=Math.max(...counts),bestIndex=counts.indexOf(best),total=counts.reduce((a,b)=>a+b,0),weekXP=days.reduce((a,d)=>a+pointsOn(d),0);return `<div class="stats"><div class="card"><div class="muted">Heti teljesítések</div><div class="statnum">${total}</div></div><div class="card"><div class="muted">Heti XP</div><div class="statnum">${weekXP}</div></div></div><div class="card"><div class="name">Legjobb nap: ${['Hétfő','Kedd','Szerda','Csütörtök','Péntek','Szombat','Vasárnap'][bestIndex]}</div><div class="muted">${best} teljesítés · ${state.questClaims.filter(k=>k.endsWith(start)).length} heti küldetés teljesítve</div></div>`}
function weeklyXPChart(){
 const dates=Array.from({length:7},(_,i)=>shift(day(),i-6));
 const values=dates.map(d=>Math.max(0,pointsOn(d)));const max=Math.max(1,...values);
 return `<div class="card"><h2 style="margin-top:0">📊 XP az elmúlt 7 napban</h2><div class="xp-chart" role="img" aria-label="Elmúlt 7 nap XP teljesítménye">${dates.map((d,i)=>`<div class="xp-column"><strong>${values[i]}</strong><div class="xp-track"><div class="xp-bar" style="height:${values[i]?Math.max(5,values[i]/max*100):0}%"></div></div><small>${['H','K','Sze','Cs','P','Szo','V'][weekday(d)]}</small></div>`).join('')}</div></div>`;
}
function habitStats(){
 const habits=state.tasks.filter(t=>t.kind==='habit');
 return `<h2>Szokásonkénti statisztikák</h2>${habits.length?habits.map(t=>{const entries=state.history.filter(h=>h.type==='task'&&h.taskId===t.id),total=entries.length,week=entries.filter(h=>h.date>=shift(day(),-6)&&h.date<=day()).length,earned=entries.reduce((n,h)=>n+Number(h.points||0),0),series=streak(t);return `<div class="card habit-stats"><div class="flex between"><button class="btn small alt" data-action="habitCalendar" data-id="${esc(t.id)}">${esc(t.emoji)} ${esc(t.name)} · 📅 Naptár</button><span class="badge">${esc(t.category)}</span></div><div class="habit-stats-grid"><div><strong>${total}</strong><small>Összes teljesítés</small></div><div><strong>${week}</strong><small>Utolsó 7 nap</small></div><div><strong>${earned} XP</strong><small>Összes XP</small></div><div><strong>${series.current} / ${series.best}</strong><small>Aktuális / rekord streak</small></div></div></div>`}).join(''):'<div class="card empty">Még nincs szokásod.</div>'}`;
}
function dailyXPGoalHTML(){const n=Math.max(0,pointsOn(day())),goal=state.settings.dailyXPGoal||100;return `<div class="card"><div class="flex between"><strong>🎯 Napi XP-cél</strong><span class="badge">${n} / ${goal} XP</span></div><div class="progress"><div class="bar" style="width:${Math.min(100,100*n/goal)}%"></div></div><p class="muted">${n>=goal?'🎉 A mai célod teljesült!':`${goal-n} XP hiányzik a napi célodhoz.`}</p></div>`}
function habitCalendarModal(t,month=dateKey(new Date()).slice(0,7)){const first=month+'-01',dt=fromKey(first),count=new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate(),offset=weekday(first);const cells=Array.from({length:offset},()=>'<span></span>').concat(Array.from({length:count},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0');return `<span class="calendar-day ${isDone(t,d)?'calendar-done':isPaused(t,d)?'calendar-rest':''}" title="${d}">${i+1}</span>`}));const prev=dateKey(new Date(dt.getFullYear(),dt.getMonth()-1,1)).slice(0,7),next=dateKey(new Date(dt.getFullYear(),dt.getMonth()+1,1)).slice(0,7);modal(`<h2>${esc(t.emoji)} ${esc(t.name)}</h2><div class="flex between"><button class="btn small alt" data-action="habitCalendar" data-id="${esc(t.id)}" data-month="${prev}">‹</button><strong>${dt.toLocaleDateString('hu-HU',{year:'numeric',month:'long'})}</strong><button class="btn small alt" data-action="habitCalendar" data-id="${esc(t.id)}" data-month="${next}">›</button></div><div class="calendar-grid">${['H','K','Sze','Cs','P','Szo','V'].map(x=>`<b>${x}</b>`).join('')}${cells.join('')}</div><p class="muted">🟢 Teljesítve · 🟣 Pihenőnap · ${t.days.filter(d=>d.startsWith(month)).length} teljesítés ebben a hónapban</p><button class="btn alt" data-action="close">Bezárás</button>`)}
function weekChallenges(){const start=weekStart(day()),end=shift(start,6);return state.weeklyChallenges.map(c=>{const t=state.tasks.find(t=>t.id===c.taskId),progress=t?t.days.filter(d=>d>=start&&d<=end).length:0,claimed=(c.claimed||[]).includes(start);return `<div class="item"><div class="grow"><div class="name">🏁 ${esc(t?.name||'Törölt szokás')}</div><div class="muted">${Math.min(progress,c.target)}/${c.target} alkalom ezen a héten · +${c.bonus} XP</div><div class="progress"><div class="bar" style="width:${Math.min(100,100*progress/c.target)}%"></div></div></div><button class="btn small" data-action="challengeClaim" data-id="${esc(c.id)}" ${progress<c.target||claimed?'disabled':''}>${claimed?'Átvéve':'Átvétel'}</button><button class="btn small alt" data-action="challengeDelete" data-id="${esc(c.id)}" aria-label="Kihívás törlése">×</button></div>`}).join('')}
function weeklyPlanner(){const start=weekStart(selectedDate);return `<div class="week-planner">${Array.from({length:7},(_,i)=>{const d=shift(start,i),items=state.tasks.filter(t=>t.kind==='todo'&&(t.dueDate||t.created)===d);return `<div class="planner-day"><strong>${['H','K','Sze','Cs','P','Szo','V'][i]} · ${fromKey(d).getDate()}</strong>${items.map(t=>`<div class="planner-item"><span class="planner-task-name ${t.days.length?'planner-completed':''}">${t.days.length?'✓ ':''}${esc(t.emoji)} ${esc(t.name)}</span><select data-planner-move="${esc(t.id)}" aria-label="Áthelyezés másik napra"><option value="">Áthelyezés…</option>${Array.from({length:7},(_,j)=>`<option value="${shift(start,j)}" ${j===i?'disabled':''}>${['H','K','Sze','Cs','P','Szo','V'][j]}</option>`).join('')}</select></div>`).join('')||'<small class="muted">Nincs egyszeri teendő</small>'}</div>`}).join('')}</div>`}
function milestoneHTML(){return `<h2>🏅 Mérföldkövek</h2><div class="card">${state.tasks.filter(t=>t.kind==='habit').map(t=>{const n=t.days.length;return `<div class="item"><span>${esc(t.emoji)}</span><div class="grow"><strong>${esc(t.name)}</strong><div class="muted">${n} teljesítés</div><div class="milestone-badges">${[10,30,100].map(v=>`<span class="badge ${n>=v?'':'locked-badge'}">${n>=v?'🏅':'🔒'} ${v}</span>`).join('')}</div></div></div>`}).join('')||'<p class="muted">Még nincs szokás.</p>'}</div>`}
function rewardHistoryHTML(){const records=state.history.filter(h=>h.type==='reward').slice().reverse();return `<h2>🎁 Beváltási előzmények</h2><div class="card"><p class="muted">Összes elköltött XP: ${records.reduce((a,h)=>a+Number(h.points||0),0)} XP</p>${records.map(h=>`<div class="item"><span class="grow">${esc(h.name)}<small class="muted"> · ${esc(h.date)}</small></span><strong>−${h.points} XP</strong></div>`).join('')||'<p class="muted">Még nem váltottál be jutalmat.</p>'}</div>`}
function xpDetailModal(){
 const entries=state.history.filter(h=>['task','quest','focus','challenge'].includes(h.type)).slice().reverse();
 const grouped=new Map();for(const h of entries){const key=h.taskId||h.type+':'+h.name;const g=grouped.get(key)||{name:h.name||'Ismeretlen',points:0,count:0};g.points+=Number(h.points||0);g.count++;grouped.set(key,g)}
 const list=[...grouped.values()].sort((a,b)=>b.points-a.points);
 modal(`<h2>✨ XP részletező</h2><p class="muted">Összes megszerzett XP: <strong>${xp()} XP</strong> · Szint ${level()}</p><p class="muted">Az XP nem csökken jutalombeváltáskor. A feladatok törlése sem törli a megszerzett XP-t.</p><h3>Honnan származik az XP?</h3><div class="xp-breakdown">${list.map(g=>`<div class="item"><div class="grow"><div class="name">${esc(g.name)}</div><div class="muted">${g.count} teljesítés / bónusz</div></div><strong>+${g.points} XP</strong></div>`).join('')||'<div class="empty">Még nincs megszerzett XP.</div>'}</div><div class="actions"><button class="btn alt" data-action="close">Bezárás</button></div>`)
}
const NAV_ITEMS=[["today", "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z\"/></svg>", "Ma"], ["planner", "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M7 3v4M17 3v4M3 10h18M8 14h3M8 18h3M15 14h2\"/></svg>", "Tervező"], ["tasks", "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"4\" y=\"3\" width=\"16\" height=\"18\" rx=\"2\"/><path d=\"m8 10 2 2 4-4M8 17h8\"/></svg>", "Feladatok"], ["rewards", "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"3\" y=\"8\" width=\"18\" height=\"13\" rx=\"2\"/><path d=\"M12 8v13M3 12h18M12 8C6 8 5 6 6 4c2-3 6 1 6 4Zm0 0c6 0 7-2 6-4-2-3-6 1-6 4Z\"/></svg>", "Jutalmak"], ["stats", "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M4 20V11M10 20V5M16 20v-9M22 20V8\"/></svg>", "Statisztika"], ["focus", "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"13\" r=\"8\"/><path d=\"M12 9v5l3 2M9 2h6\"/></svg>", "Fókusz"], ["settings", "<svg viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M19 13.5a7.5 7.5 0 0 0 0-3l2-1.5-2-3.5-2.4 1a8 8 0 0 0-2.6-1.5L13.5 2h-3L10 5a8 8 0 0 0-2.6 1.5L5 5.5 3 9l2 1.5a7.5 7.5 0 0 0 0 3L3 15l2 3.5 2.4-1a8 8 0 0 0 2.6 1.5l.5 3h3l.5-3a8 8 0 0 0 2.6-1.5l2.4 1L21 15z\"/></svg>", "Egyéb"]];

function navigationHTML(){
 const primary=NAV_ITEMS.filter(([key])=>['today','planner','rewards','stats'].includes(key));
 return primary.map(([key,icon,label])=>`<button class="tab ${tab===key?'active':''}" data-action="tab" data-tab="${key}" aria-label="${label}" aria-current="${tab===key?'page':'false'}"><span class="tab-icon">${icon}</span><span class="nav-label">${label==='Statisztika'?'Fejlődés':label}</span></button>`).join('')+`<button class="tab ${['tasks','focus','settings'].includes(tab)?'active':''}" data-action="more" aria-label="Továbbiak"><span class="tab-icon"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/></svg></span><span class="nav-label">Továbbiak</span></button>`;
}
function moreModal(){
 modal(`<div class="sheet-heading"><div><span class="section-kicker">A TE LEVELUPOD</span><h2>További lehetőségek</h2></div><button class="icon-button" data-action="close" aria-label="Bezárás">×</button></div><div class="more-menu">${NAV_ITEMS.filter(([key])=>['tasks','focus','settings'].includes(key)).map(([key,icon,label])=>`<button data-action="tab" data-tab="${key}"><span class="menu-icon">${icon}</span><span>${key==='settings'?'Beállítások':label}<small>${({tasks:'Szokások és pihenőnapok',focus:'Egy kis idő csak a feladatra',settings:'Mentések, célok és testreszabás'})[key]}</small></span><svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></button>`).join('')}</div>`);
}
function homeHTML(){
 const visible=state.tasks.filter(t=>scheduled(t,selectedDate)),done=visible.filter(t=>isDone(t,selectedDate)).length;
 const earned=xp(),within=earned%200,percent=within/200*100,wish=state.rewards.find(r=>r.id===state.wishId);
 const groups={
  level:`<button class="card hero level-card xp-detail-trigger" data-action="xpDetail" aria-label="XP részletezése: ${level()}. szint, ${within} a 200 XP-ből"><span class="level-copy"><span class="section-kicker">MINDEN LÉPÉS SZÁMÍT</span><strong>Apró lépések.<br>Nagy fejlődés.</strong><span class="level-caption">Még <b>${200-within} XP</b> a következő szintig <svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></span></span><span class="level-ring"><svg viewBox="0 0 120 120" aria-hidden="true"><circle class="ring-track" cx="60" cy="60" r="51"/><circle class="ring-value" cx="60" cy="60" r="51" pathLength="100" stroke-dasharray="${percent} 100"/></svg><span class="ring-label"><span class="ring-star" aria-hidden="true">✧</span><b>${level()}</b><small>SZINT</small></span></span><span class="level-footer"><span>✦ ${earned} összes XP</span><span>${within} / 200 XP</span></span></button>`,
  progress:`<div class="card daily-progress"><div class="flex between"><div><span class="section-kicker">${selectedDate===day()?'A MAI LENDÜLETED':'NAPI HALADÁS'}</span><p><strong>${done}</strong><span> / ${visible.length} feladat teljesítve</span></p></div><span class="daily-xp">+${pointsOn(selectedDate)} XP</span></div><div class="progress" role="progressbar" aria-label="Napi feladatok" aria-valuemin="0" aria-valuemax="${Math.max(1,visible.length)}" aria-valuenow="${done}"><div class="bar" style="width:${visible.length?100*done/visible.length:0}%"></div></div></div>`,
  tasks:`<div class="flex between section-heading"><div><span class="section-kicker">EGY LÉPÉSSEL ELŐRÉBB</span><h2>${selectedDate===day()?'Mai küldetések':'A nap küldetései'}</h2></div><button class="btn small alt add-task" data-action="editTask"><span aria-hidden="true">＋</span> Új feladat</button></div>${visible.length?groupedTasks(visible,taskHTML):'<div class="card empty"><span class="empty-spark" aria-hidden="true">✧</span><strong>Van hely egy új kezdetnek.</strong><p>Adj hozzá egy szokást vagy teendőt erre a napra.</p><button class="btn" data-action="editTask">Első küldetés hozzáadása</button></div>'}`,
  quests:selectedDate===day()?`<div class="section-heading"><span class="section-kicker">EXTRA MOTIVÁCIÓ</span><h2>Napi és heti bónuszok</h2></div><div class="card bonus-card">${quests().map(q=>`<div class="item"><span class="bonus-spark" aria-hidden="true">✦</span><div class="grow"><div class="name">${q.name}</div><div class="muted">${Math.min(q.progress,q.target)} / ${q.target} teljesítés · +${q.points} XP</div></div><button class="btn small" data-action="claim" data-id="${q.key}" ${q.progress<q.target||state.questClaims.includes(q.key)?'disabled':''}>${state.questClaims.includes(q.key)?'Átvéve':'Átvétel'}</button></div>`).join('')}</div>`:'',
  wish:wish?`<div class="section-heading"><span class="section-kicker">MEGDOLGOZOL ÉRTE. MEGÉRDEMLED.</span><h2>A következő örömöd</h2></div><div class="card wish-card"><span class="wish-emoji" aria-hidden="true">${esc(wish.emoji)}</span><div class="grow"><span class="section-kicker">A JUTALOMCÉLOD</span><div class="name">${esc(wish.name)}</div><div class="progress"><div class="bar" style="width:${Math.max(0,Math.min(100,wallet()/wish.cost*100))}%"></div></div><div class="muted">${wallet()>=wish.cost?'Már elérted! Váltsd be a jutalomboltban.':`Már csak ${wish.cost-wallet()} pont hiányzik.`}</div></div><button class="icon-button" data-action="tab" data-tab="rewards" aria-label="Jutalombolt megnyitása"><svg class="arrow-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></button></div>`:''
 };
 const overdue=state.tasks.filter(t=>t.kind==='todo'&&!t.days.length&&(t.dueDate||t.created)<day());
 const order=[...new Set([...state.ui.blocks,...Object.keys(groups)])];
 return `<p class="home-intro">Minden kis győzelem közelebb visz.</p>${dateStrip()}<div class="home-blocks">${order.filter(k=>groups[k]).map(k=>`<section class="home-block home-block-${k}" data-home-block="${k}" ${state.ui.hidden.includes(k)?'hidden':''}>${groups[k]}</section>`).join('')}</div>${overdue.length?`<section class="card overdue-card"><h2>Korábbról maradt · ${overdue.length}</h2>${overdue.map(t=>`<div class="item"><span class="grow">${esc(t.emoji)} ${esc(t.name)} <small class="muted">${esc(t.dueDate||t.created)}</small></span><button class="btn small alt" data-action="carry" data-id="${esc(t.id)}">Mára teszem</button></div>`).join('')}<button class="btn small alt" data-action="carryAll">Összes áthozása</button></section>`:''}${dailyXPGoalHTML()}<h2>Heti kihívások</h2><div class="card">${weekChallenges()||'<p class="muted">Egy kis kihívás, egy nagyobb lendület. A Beállításokban készíthetsz sajátot.</p>'}</div>${timerHTML()}`;
}

function render(){document.body.dataset.view=recoveryRequired?'recovery':tab;if(recoveryRequired){$('#pageTitle').textContent='Mentés helyreállítása';$('#wallet').textContent='–';$('#nav').replaceChildren();$('#view').innerHTML=recoveryHTML();return}const titles={today:'Szia, Dominik!',tasks:'Feladataim',rewards:'Jutalombolt',stats:'Fejlődésem',focus:'Fókusz',settings:'Beállítások',planner:'Heti tervező'};$('#pageTitle').textContent=titles[tab];$('#wallet').textContent=wallet();$('#nav').innerHTML=navigationHTML();let html='';
if(tab==='today')html=homeHTML();
 if(tab==='tasks'){const taskManage=t=>`<div class="item manage-row draggable-task"><button type="button" class="emoji emoji-edit" data-action="editTask" data-id="${esc(t.id)}" aria-label="${esc(t.name)} szerkesztése" title="Feladat szerkesztése">${esc(t.emoji)}</button><div class="grow"><div class="name">${esc(t.name)}</div><div class="muted"><span class="priority priority-${esc(t.priority||'medium')}">${(t.priority||'medium').toUpperCase()}</span> · ${esc(t.category)} · +${t.points} XP · ${t.days.length} teljesítés</div>${t.kind==='habit'?`<div class="muted">🔥 ${streak(t).current} · rekord ${streak(t).best}</div>`:`<div class="muted">📅 ${esc(t.dueDate||t.created)}</div>`}</div></div>${t.kind==='habit'?`<div class="actions tasktools">${t.kind==='habit'?`<button class="rest-button ${isPaused(t)?'rest-active':''}" data-action="pause" data-id="${esc(t.id)}">${isPaused(t)?'▶ Pihenőnap visszavonása':'☾ Pihenőnap beállítása mára'}</button>`:''}</div>`:''}`;html=`<div class="flex between"><div class="muted">Itt a rendszeres szokásaidat kezelheted. Az egyszeri teendők a választott napon, a főoldalon láthatók.</div><button class="btn small" data-action="editTask">+ Új</button></div>${[['habit','🔁 Szokások']].map(([kind,label])=>{let arr=state.tasks.filter(t=>t.kind===kind),key='manage:'+kind,collapsed=collapsedGroups.has(key);return `<section class="manage-section"><button class="category-heading category-toggle" data-action="collapse" data-group="${key}" aria-expanded="${!collapsed}"><span>${label}</span><span class="category-meta">${arr.length} ${collapsed?'⌄':'⌃'}</span></button>${collapsed?'':`<div class="card">${arr.length?sortedTasks(arr).map(taskManage).join(''):'<div class="empty">Még nincs ilyen feladatod.</div>'}</div>`}</section>`}).join('')}`}
if(tab==='rewards'){html=`<div class="card hero"><div class="muted">Elkölthető egyenleg</div><div class="big">🪙 ${wallet()} XP</div><div class="muted">Az XP megmarad, a XPokat jutalmakra költheted.</div></div><div class="flex between"><h2>Jutalmak</h2><button class="btn small alt" data-action="editReward">+ Új</button></div><div class="card">${state.rewards.map(r=>`${rewardHTML(r)}<div class="actions tasktools"><button class="btn small alt" data-action="editReward" data-id="${esc(r.id)}">Szerkesztés</button><button class="btn small alt" data-action="wish" data-id="${esc(r.id)}">${state.wishId===r.id?'Cél törlése':'🎯 Célként kitűzöm'}</button></div>`).join('')||'<div class="empty">Adj hozzá egy jutalmat!</div>'}</div>${rewardHistoryHTML()}`}
if(tab==='stats'){html=`${weeklyXPChart()}${habitStats()}${milestoneHTML()}<div class="stats"><div class="card"><div class="muted">Összes XP</div><div class="statnum">${xp()}</div></div><div class="card"><div class="muted">Szint</div><div class="statnum">${level()}</div></div></div><h2>Heti összefoglaló</h2>${weeklySummary()}<h2>Aktivitási naptár</h2><div class="card">${heatmap()}</div><h2>Achievementek</h2><div class="card">${achievements().map(a=>`<div class="item"><span class="emoji">${a.icon}</span><div class="grow"><div class="name">${a.name}</div><div class="muted">${a.desc}</div></div><span class="badge" style="${a.ok?'':'background:#f1f3f7;color:#8b96a8'}">${a.ok?'Feloldva':'Zárolva'}</span></div>`).join('')}</div><h2>📦 Teljesített egyszeri teendők</h2><div class="card">${state.tasks.filter(t=>t.kind==='todo'&&t.days.length).map(t=>`<div class="item"><span>${esc(t.emoji)} ${esc(t.name)}</span><small>${esc(t.days[0])}</small></div>`).join('')||'<p class="muted">Még nincs archivált teendő.</p>'}</div><h2>Utolsó események</h2><div class="card">${state.history.slice(-15).reverse().map(h=>`<div class="item"><div class="grow"><div class="name">${esc(h.name)}</div><div class="muted">${esc(h.date)} · ${esc(h.type)}</div></div><strong>${h.type==='reward'?'−':'+'}${h.points}</strong></div>`).join('')||'<div class="empty">Nincs esemény.</div>'}</div>`}
if(tab==='planner'){html=`<div class="flex between"><h2>🗓️ Heti tervező</h2><button class="btn small alt" data-action="editTask">+ Új</button></div>${dateStrip()}<p class="muted">Az egyszeri teendőket a legördülő menüvel másik napra helyezheted. A szokások ismétlődési rendje nem változik.</p>${weeklyPlanner()}`}
if(tab==='focus'){html=`<div class="card hero"><div class="muted">FÓKUSZ IDŐZÍTŐ</div><div class="timer" id="timerText">${fmtTime(focus.remaining)}</div><div class="actions"><button class="btn alt" data-action="focusDuration" data-min="25">25 perc</button><button class="btn alt" data-action="focusDuration" data-min="50">50 perc</button></div></div><div class="card"><div class="field"><label>Feladat (opcionális)</label><select id="focusTask"><option value="">Általános fókusz</option>${state.tasks.map(t=>`<option value="${esc(t.id)}" ${focus.taskId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="actions"><button class="btn" data-action="focusStart">${focus.running?'Szünet':'Indítás'}</button><button class="btn alt" data-action="focusReset">Visszaállítás</button></div><p class="muted">A teljes fókuszblokk végén +${focus.duration===25?15:35} XP jár. A jutalom csak az időzítő befejeződésekor írható jóvá, ha az oldal működésben marad. iOS-en a háttérben futás nem garantált.</p><div class="name">Teljesített fókuszblokkok: ${state.focusSessions.length}</div></div>`}
if(tab==='settings'){html=`<div class="card"><h2 style="margin-top:0">Emlékeztetők</h2><p class="muted">A háttérben érkező push értesítésekhez telepítsd az alkalmazást az iPhone főképernyőjére, és állíts be egy push szervert. A helyi értesítések csak nyitott alkalmazásban működnek.</p><div class="field"><label>Esti emlékeztető</label><input id="reminderTime" type="time" value="${esc(state.settings.reminder)}"></div><label class="flex"><input type="checkbox" id="reminderEnabled" ${state.settings.reminderEnabled?'checked':''}> Emlékeztető bekapcsolása</label><div class="actions" style="margin-top:12px"><button class="btn alt" data-action="saveReminder">Mentés</button><button class="btn alt" data-action="notifyPermission">Értesítési engedély</button></div><div class="field"><label>Push szerver URL (HTTPS)</label><input id="pushServer" type="url" placeholder="https://levelup-push.example.com" value="${esc(state.settings.pushServer||'')}"></div><div class="actions"><button class="btn" data-action="pushEnable">🔔 Háttér push bekapcsolása</button><button class="btn alt" data-action="pushDisable">Kikapcsolás</button><button class="btn alt" data-action="pushTest">Tesztértesítés</button></div></div><div class="card"><h2>🎯 Napi XP-cél</h2><form id="dailyGoalForm" class="flex"><input type="number" name="dailyGoal" min="1" max="10000" value="${state.settings.dailyXPGoal||100}" required><button class="btn" type="submit">Mentés</button></form></div><div class="card"><h2>🏁 Heti kihívás hozzáadása</h2><form id="challengeForm"><div class="field"><label>Szokás</label><select name="taskId" required>${state.tasks.filter(t=>t.kind==='habit').map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Heti teljesítési cél (alkalom)</label><input name="target" type="number" min="1" max="7" value="4" required></div><div class="field"><label>Jutalom XP</label><input name="bonus" type="number" min="1" max="500" value="50" required></div><button class="btn" type="submit">Kihívás létrehozása</button></form></div><div class="card"><h2>Saját kategóriák</h2><form id="categoryForm" class="flex"><input name="category" maxlength="32" placeholder="Új kategória" required><button class="btn" type="submit">Hozzáadás</button></form>${state.categories.map(c=>`<div class="item"><span class="grow">${esc(c)}</span><button class="btn small alt" data-action="deleteCategory" data-category="${esc(c)}" ${state.tasks.some(t=>t.category===c)?'disabled title="Használatban lévő kategória"':''}>Törlés</button></div>`).join('')}</div><div class="card"><h2>Kezdőlap testreszabása</h2><p class="muted">Kapcsold ki a blokkokat, vagy mozgasd őket fel/le.</p>${state.ui.blocks.map(k=>`<div class="item"><input type="checkbox" data-block-toggle="${k}" ${state.ui.hidden.includes(k)?'':'checked'}><span class="grow">${({level:'Szint és XP',progress:'Napi haladás',tasks:'Feladatok',quests:'Küldetések',wish:'Jutalomcél'})[k]||k}</span><button class="btn small alt" data-action="blockMove" data-id="${k}" data-dir="-1">↑</button><button class="btn small alt" data-action="blockMove" data-id="${k}" data-dir="1">↓</button></div>`).join('')}</div><div class="card"><h2 style="margin-top:0">Biztonsági mentés</h2><p class="muted">A régi LevelUp 1.0 mentése automatikusan átalakul. Az adatok továbbra is ezen a webhelycímen, ebben a böngészőben tárolódnak. Frissítés előtt készíts exportot!</p><div class="actions"><button class="btn" data-action="export">⬇ JSON export</button><button class="btn alt" data-action="import">⬆ JSON import</button></div><input type="file" id="importFile" accept=".json,application/json" class="hidden"><hr><button class="btn danger" data-action="reset">Összes adat törlése</button></div><div class="card"><div class="name">LevelUp 7.1</div><p class="muted">Helyi adatmentés · 200 XP / szint · szokássorozatok · heti célok · fókuszidőzítő</p></div>`}
$('#view').innerHTML=html;}
function modal(html){$('#modalRoot').innerHTML=`<div class="modal"><div class="sheet">${html}</div></div>`}function close(){$('#modalRoot').replaceChildren()}
function taskModal(t){let days=t?.weekdays||[0,1,2,3,4,5,6];modal(`<h2>${t?'Feladat szerkesztése':'Új feladat'}</h2><form id="taskForm"><div class="field"><label>Név</label><input name="name" required maxlength="90" value="${esc(t?.name||'')}"></div><div class="field"><label>Emoji kiválasztása</label><div class="emoji-grid" role="group" aria-label="Emoji választó">${EMOJIS.map(e=>`<button type="button" class="emoji-option ${e===(t?.emoji||'✨')?'chosen':''}" data-emoji="${e}" aria-label="${e}" aria-pressed="${e===(t?.emoji||'✨')}">${e}</button>`).join('')}</div><input type="hidden" name="emoji" value="${esc(t?.emoji||'✨')}"></div><div class="field"><label>XP érték</label><input name="points" type="number" min="1" max="1000" required value="${t?.points||20}"></div><div class="field"><label>Kategória</label><select name="category">${state.categories.map(c=>`<option ${t?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Prioritás</label><select name="priority">${[['low','Low – alacsony'],['medium','Medium – közepes'],['high','High – magas']].map(([v,l])=>`<option value="${v}" ${(t?.priority||'medium')===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Típus</label><select name="kind"><option value="habit" ${t?.kind==='habit'?'selected':''}>Szokás</option><option value="todo" ${t?.kind==='todo'?'selected':''}>Egyszeri teendő</option></select></div><div class="field" data-only="todo"><label>Feladat napja</label><input type="date" name="dueDate" value="${esc(t?.dueDate||(!t?selectedDate:t.created||day()))}"></div><div class="field" data-only="habit"><label>Ismétlődés</label><select name="frequency"><option value="daily" ${t?.frequency==='daily'?'selected':''}>Minden nap</option><option value="weekdays" ${t?.frequency==='weekdays'?'selected':''}>Kijelölt napokon</option><option value="weekly" ${t?.frequency==='weekly'?'selected':''}>Heti X alkalommal</option></select></div><div class="field" data-frequency="weekdays"><label>Napok (H–V)</label><div class="daychecks">${['H','K','Sze','Cs','P','Szo','V'].map((d,i)=>`<label><input type="checkbox" name="weekday" value="${i}" ${days.includes(i)?'checked':''}>${d}</label>`).join('')}</div></div><div class="field" data-frequency="weekly"><label>Heti cél (1–7)</label><input type="number" name="weeklyTarget" min="1" max="7" value="${t?.weeklyTarget||3}"></div><div class="field" data-only="habit"><label>Időszakos cél (opcionális)</label><select name="goalPeriod"><option value="">Nincs</option><option value="week" ${t?.goal?.period==='week'?'selected':''}>Heti</option><option value="month" ${t?.goal?.period==='month'?'selected':''}>Havi</option></select><input type="number" name="goalTarget" min="1" step="0.1" placeholder="Célmennyiség" value="${t?.goal?.target||''}"><input name="goalUnit" maxlength="18" placeholder="Egység, pl. km, perc" value="${esc(t?.goal?.unit||'')}"></div><div class="actions"><button class="btn" type="submit">Mentés</button><button class="btn alt" type="button" data-action="close">Mégse</button>${t?`<button class="btn danger" type="button" data-action="deleteTask" data-id="${esc(t.id)}">Törlés</button>`:''}</div></form>`);const form=$('#taskForm');const syncFields=()=>{const kind=form.elements.kind.value,frequency=form.elements.frequency.value;form.querySelectorAll('[data-only]').forEach(el=>el.hidden=el.dataset.only!==kind);form.querySelectorAll('[data-frequency]').forEach(el=>el.hidden=kind!=='habit'||el.dataset.frequency!==frequency)};form.elements.kind.addEventListener('change',syncFields);form.elements.frequency.addEventListener('change',syncFields);syncFields();$('#taskForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),p=Number(f.get('points')),w=Number(f.get('weeklyTarget'));if(!Number.isInteger(p)||p<1||p>1000||(f.get('kind')==='habit'&&f.get('frequency')==='weekly'&&(!Number.isInteger(w)||w<1||w>7)))return toast('Ellenőrizd a XPértéket és a heti célt.');let item={...t,id:t?.id||id(),name:String(f.get('name')).trim(),emoji:String(f.get('emoji')).trim()||'✨',points:p,kind:f.get('kind'),frequency:f.get('kind')==='todo'?'once':f.get('frequency'),category:f.get('category'),priority:f.get('priority'),weekdays:f.getAll('weekday').map(Number),weeklyTarget:w,subtasks:t?.subtasks||[],days:t?.days||[],paused:t?.paused||[],created:t?.created||selectedDate,dueDate:String(f.get('dueDate')||selectedDate),order:t?.order||0,goal:f.get('kind')==='habit'&&f.get('goalPeriod')&&Number(f.get('goalTarget'))>0?{period:f.get('goalPeriod'),target:Number(f.get('goalTarget')),unit:String(f.get('goalUnit')||'alkalom').trim()}:null};if(!item.name||(item.kind==='habit'&&item.frequency==='weekdays'&&!item.weekdays.length))return toast('Adj meg nevet és legalább egy napot.');state.tasks=t?state.tasks.map(x=>x.id===t.id?item:x):[...state.tasks,item];save();close();render();toast('Feladat mentve')}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-emoji]');if(!b)return;const form=b.closest('form');if(!form)return;form.querySelector('[name=emoji]').value=b.dataset.emoji;form.querySelectorAll('[data-emoji]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b))})});
function rewardModal(r){modal(`<h2>${r?'Jutalom szerkesztése':'Új jutalom'}</h2><form id="rewardForm"><div class="field"><label>Név</label><input name="name" required maxlength="90" value="${esc(r?.name||'')}"></div><div class="field"><label>Emoji kiválasztása</label><div class="emoji-grid">${EMOJIS.map(e=>`<button type="button" class="emoji-option ${e===(r?.emoji||'🎁')?'chosen':''}" data-emoji="${e}" aria-pressed="${e===(r?.emoji||'🎁')}">${e}</button>`).join('')}</div><input type="hidden" name="emoji" value="${esc(r?.emoji||'🎁')}"></div><div class="field"><label>Ár (pont)</label><input name="cost" type="number" min="1" max="100000" required value="${r?.cost||100}"></div><div class="field"><label>Időkorlát percben (0 = nincs)</label><input name="minutes" type="number" min="0" max="1440" value="${r?.minutes||0}"></div><div class="actions"><button class="btn" type="submit">Mentés</button><button class="btn alt" type="button" data-action="close">Mégse</button>${r?`<button class="btn danger" type="button" data-action="deleteReward" data-id="${esc(r.id)}">Törlés</button>`:''}</div></form>`);$('#rewardForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),cost=Number(f.get('cost'));if(!Number.isInteger(cost)||cost<1||cost>100000)return toast('Hibás ár');let item={id:r?.id||id(),name:String(f.get('name')).trim(),emoji:String(f.get('emoji')).trim()||'🎁',cost,minutes:Math.max(0,Math.min(1440,Number(f.get('minutes'))||0))};if(!item.name)return;state.rewards=r?state.rewards.map(x=>x.id===r.id?item:x):[...state.rewards,item];save();close();render()}}
function subtasksModal(t){let key=t.id+':'+selectedDate,checks=state.subtaskChecks[key]||[];modal(`<h2>${esc(t.name)}</h2><p class="muted">A részfeladatok napi kipipálása nem ad külön XPot.</p>${t.subtasks.map((s,i)=>`<label class="item"><input type="checkbox" data-sub="${i}" ${checks.includes(i)?'checked':''}> ${esc(s)}</label>`).join('')}<button class="btn alt" data-action="close">Bezárás</button>`);$('#modalRoot').onchange=e=>{if(!e.target.matches('[data-sub]'))return;let n=Number(e.target.dataset.sub),set=new Set(state.subtaskChecks[key]||[]);e.target.checked?set.add(n):set.delete(n);state.subtaskChecks[key]=[...set];save()}}
function toggle(t){let d=selectedDate;if(d>day())return toast('Jövőbeli feladatot még nem teljesíthetsz.');let done=isDone(t,d),before=level(),old=achievements().filter(a=>a.ok).map(a=>a.name);if(isPaused(t,d)&&!done)return toast('Ez a szokás ma szünetel.');if(!done&&!scheduled(t,d))return toast('Ez a feladat ma nem esedékes.');if(done){let index=state.history.findIndex(h=>h.type==='task'&&h.taskId===t.id&&(t.kind==='todo'||h.date===d));if(index<0)return toast('Nem vonható vissza');let h=state.history[index];state.history.splice(index,1);t.days=t.kind==='todo'?[]:t.days.filter(x=>x!==d);state.ledger.push({id:id(),amount:-h.points,type:'reversal',date:d})}else{t.days.push(d);state.ledger.push({id:id(),amount:t.points,type:'task',date:d});state.history.push({id:id(),type:'task',taskId:t.id,name:t.name,points:t.points,date:d})}save();render();if(!done){celebrate(t.points,level()>before?`🎉 LEVEL UP! ${level()}. szint`:achievements().some(a=>a.ok&&!old.includes(a.name))?'🏅 Új achievement!':'Küldetés teljesítve!')}else toast('Teljesítés visszavonva')}
function claim(k){let q=quests().find(q=>q.key===k);if(!q||q.progress<q.target||state.questClaims.includes(k))return;state.questClaims.push(k);state.ledger.push({id:id(),amount:q.points,type:'quest',date:day()});state.history.push({id:id(),type:'quest',name:q.name,points:q.points,date:day()});save();render();celebrate(q.points,'Küldetésbónusz!')}
const fmtTime=n=>`${String(Math.floor(Math.max(0,n)/60)).padStart(2,'0')}:${String(Math.max(0,n)%60).padStart(2,'0')}`;
function focusTick(){if(!focus.running)return;focus.remaining=Math.max(0,Math.ceil((focus.end-Date.now())/1000));let el=$('#timerText');if(el)el.textContent=fmtTime(focus.remaining);if(focus.remaining===0){focus.running=false;let points=focus.duration===25?15:35;state.focusSessions.push({id:id(),date:day(),minutes:focus.duration,taskId:focus.taskId});state.ledger.push({id:id(),amount:points,type:'focus',date:day()});state.history.push({id:id(),type:'focus',name:`${focus.duration} perc fókusz`,points,date:day()});focus.remaining=focus.duration*60;save();render();celebrate(points,'Fókuszblokk teljesítve!')}}
function remind(){if(!state.settings.reminderEnabled)return;let now=new Date(),hhmm=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`,stamp='levelup-reminder-'+day();if(hhmm===state.settings.reminder&&sessionStorage.getItem(stamp)!=='1'){sessionStorage.setItem(stamp,'1');toast('🌙 Esti LevelUp ellenőrzés!');if('Notification'in window&&Notification.permission==='granted')new Notification('LevelUp – esti emlékeztető',{body:'Nézd meg a mai küldetéseidet!'});}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,k=b.dataset.id,t=state.tasks.find(x=>x.id===k),r=state.rewards.find(x=>x.id===k);if(a==='habitCalendar'&&t){habitCalendarModal(t,b.dataset.month||day().slice(0,7));return}if(a==='challengeClaim'){const c=state.weeklyChallenges.find(x=>x.id===k),w=weekStart(day()),t=state.tasks.find(x=>x.id===c?.taskId);if(c&&t&&t.days.filter(d=>d>=w&&d<=shift(w,6)).length>=c.target&&!(c.claimed||[]).includes(w)){c.claimed=[...(c.claimed||[]),w];state.ledger.push({id:id(),amount:c.bonus,type:'challenge',date:day()});state.history.push({id:id(),type:'challenge',name:'Heti kihívás: '+t.name,points:c.bonus,date:day()});save();render();celebrate(c.bonus,'Heti kihívás teljesítve!')}return}if(a==='challengeDelete'){if(confirm('Törlöd ezt a heti kihívást?')){state.weeklyChallenges=state.weeklyChallenges.filter(c=>c.id!==k);save();render()}return}if(a==='xpDetail'){xpDetailModal();return}if(a==='carry'&&t){t.dueDate=day();save();render();toast('Áthozva mára');return}
if(a==='carryAll'){state.tasks.filter(x=>x.kind==='todo'&&!x.days.length&&(x.dueDate||x.created)<day()).forEach(x=>x.dueDate=day());save();render();return}
if(a==='move'&&t){const peers=sortedTasks(state.tasks.filter(x=>x.category===t.category&&x.priority===t.priority&&scheduled(x,selectedDate)));const at=peers.findIndex(x=>x.id===t.id),next=peers[at+Number(b.dataset.dir)];if(next){const base=peers.map((x,i)=>({...x,order:i*10}));const a=base.find(x=>x.id===t.id),z=base.find(x=>x.id===next.id);[a.order,z.order]=[z.order,a.order];base.forEach(x=>{state.tasks.find(y=>y.id===x.id).order=x.order});save();render()}return}
if(a==='goalAdd'&&t?.goal){const input=prompt(`Mennyi ${t.goal.unit} teljesült?`,'1');if(input===null)return;const val=Number(input.replace(',','.'));if(!Number.isFinite(val)||val<=0||val>100000)return toast('Érvénytelen mennyiség');state.progressLogs.push({id:id(),taskId:t.id,date:day(),value:val});save();render();return}
if(a==='blockMove'){let i=state.ui.blocks.indexOf(k),j=i+Number(b.dataset.dir);if(j>=0&&j<state.ui.blocks.length){[state.ui.blocks[i],state.ui.blocks[j]]=[state.ui.blocks[j],state.ui.blocks[i]];save();render()}return}
if(a==='deleteCategory'){const c=b.dataset.category;if(state.tasks.some(t=>t.category===c))return toast('A kategóriában még vannak feladatok');state.categories=state.categories.filter(x=>x!==c);save();render();return}
if(a==='more'){moreModal()}else if(a==='tab'){tab=b.dataset.tab;close();render()}else if(a==='collapse'){let key=b.dataset.group;collapsedGroups.has(key)?collapsedGroups.delete(key):collapsedGroups.add(key);render()}else if(a==='dateSelect'){selectedDate=b.dataset.date;render()}else if(a==='dateShift'){selectedDate=shift(selectedDate,Number(b.dataset.offset));render()}else if(a==='dateToday'){selectedDate=day();render()}else if(a==='close')close();else if(a==='editTask')taskModal(t);else if(a==='editReward')rewardModal(r);else if(a==='toggle'&&t)toggle(t);else if(a==='claim')claim(k);else if(a==='subtasks'&&t)subtasksModal(t);else if(a==='pause'&&t){t.paused=isPaused(t)?t.paused.filter(x=>x!==day()):[...t.paused,day()];save();render()}else if(a==='wish'){state.wishId=state.wishId===k?null:k;save();render()}else if(a==='redeem'&&r&&wallet()>=r.cost&&confirm(`Beváltod: ${r.name} (${r.cost} XP)?`)){state.ledger.push({id:id(),amount:-r.cost,type:'reward',date:day()});state.history.push({id:id(),type:'reward',rewardId:r.id,name:r.name,points:r.cost,date:day()});if(r.minutes)state.activeRewards.push({id:id(),name:r.name,end:Date.now()+r.minutes*60000});save();render();toast('Jutalom beváltva!')}else if(a==='deleteTask'&&t&&confirm('Törlöd a feladatot? A korábbi XPok megmaradnak.')){state.tasks=state.tasks.filter(x=>x.id!==k);save();close();render()}else if(a==='deleteReward'&&r&&confirm('Törlöd a jutalmat?')){state.rewards=state.rewards.filter(x=>x.id!==k);if(state.wishId===k)state.wishId=null;save();close();render()}else if(a==='focusDuration'){if(focus.running)return toast('Előbb állítsd le az időzítőt');focus.duration=Number(b.dataset.min);focus.remaining=focus.duration*60;render()}else if(a==='focusStart'){if(focus.running){focusTick();focus.running=false}else{if(focus.remaining<=0)focus.remaining=focus.duration*60;focus.taskId=$('#focusTask')?.value||'';focus.running=true;focus.end=Date.now()+focus.remaining*1000}render()}else if(a==='focusReset'){focus.running=false;focus.remaining=focus.duration*60;render()}else if(a==='saveReminder'){state.settings.reminder=$('#reminderTime').value;state.settings.reminderEnabled=$('#reminderEnabled').checked;save();syncPushSettings().catch(()=>{});toast('Emlékeztető mentve')}else if(a==='pushEnable')enablePush();else if(a==='pushDisable')disablePush();else if(a==='pushTest')testPush();else if(a==='notifyPermission'){if('Notification'in window&&Notification.requestPermission)Notification.requestPermission().then(p=>toast(p==='granted'?'Értesítés engedélyezve':'Az értesítés nincs engedélyezve'));else toast('Ez a böngésző nem támogatja az értesítést')}else if(a==='export'){let blob=new Blob([recoveryRequired?originalSave:JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`levelup-${recoveryRequired?'recovery':'backup'}-${day()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}else if(a==='import')$('#importFile')?.click();else if(a==='reset'&&confirm('Biztosan törlöd az összes adatodat?')){if(replaceState(migrate(seed())))render()}});
document.addEventListener('submit',e=>{if(e.target.id==='dailyGoalForm'){e.preventDefault();state.settings.dailyXPGoal=Math.max(1,Math.min(10000,Number(e.target.elements.dailyGoal.value)||100));save();render();return}if(e.target.id==='challengeForm'){e.preventDefault();const f=new FormData(e.target);const taskId=String(f.get('taskId'));if(!state.tasks.some(t=>t.id===taskId&&t.kind==='habit'))return toast('Válassz szokást');state.weeklyChallenges.push({id:id(),taskId,target:Math.max(1,Math.min(7,Number(f.get('target'))||4)),bonus:Math.max(1,Math.min(500,Number(f.get('bonus'))||50)),claimed:[]});save();render();return}if(e.target.id==='categoryForm'){e.preventDefault();const name=e.target.elements.category.value.trim();if(!name||state.categories.includes(name))return toast('Már létező vagy üres kategória');state.categories.push(name);save();render()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-planner-move]')){const t=state.tasks.find(t=>t.id===e.target.dataset.plannerMove);if(t&&e.target.value&&t.kind==='todo'){t.dueDate=e.target.value;save();render()}return}if(e.target.matches('[data-block-toggle]')){const k=e.target.dataset.blockToggle;state.ui.hidden=e.target.checked?state.ui.hidden.filter(x=>x!==k):[...new Set([...state.ui.hidden,k])];save();render()}});
document.addEventListener('change',async e=>{if(e.target.id!=='importFile')return;try{let file=e.target.files?.[0];if(!file)return;e.target.value='';let incoming=migrate(JSON.parse(await file.text()));if(!confirm('Az importálás felülírja a jelenlegi adataidat. Folytatod?'))return;if(!replaceState(incoming))return;render();toast('Mentés importálva')}catch{toast('Érvénytelen mentésfájl')}});
save();render();setInterval(()=>{focusTick();remind();document.querySelectorAll('[data-timer]').forEach(el=>{const r=state.activeRewards.find(x=>x.id===el.dataset.timer);if(r)el.textContent=fmtTime(Math.ceil(Math.max(0,r.end-Date.now())/1000))})},1000);if('serviceWorker'in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});

// Real background Web Push: requires an independently deployed HTTPS push service.
function pushURL(){return (state.settings.pushServer||'').replace(/\/+$/,'')}
function urlBase64ToUint8Array(base64){const padding='='.repeat((4-base64.length%4)%4),raw=atob((base64+padding).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function pushRequest(path,body){const res=await fetch(pushURL()+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!res.ok)throw Error('Push szerver hiba: '+res.status);return res.json()}
async function pushSubscription(){const reg=await navigator.serviceWorker.ready;return reg.pushManager.getSubscription()}
async function syncPushSettings(){if(!pushURL())return;const sub=await pushSubscription();if(sub)await pushRequest('/api/subscribe',{subscription:sub.toJSON(),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,reminder:state.settings.reminder,enabled:state.settings.reminderEnabled})}
async function enablePush(){try{const input=$('#pushServer');if(input)state.settings.pushServer=input.value.trim().replace(/\/+$/,'');if(!/^https:\/\//.test(pushURL()))throw Error('Adj meg egy működő HTTPS push szerver címet.');if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('A készülék nem támogatja a Web Push funkciót. iPhone-on telepítsd a PWA-t a főképernyőre (iOS 16.4+).');const perm=await Notification.requestPermission();if(perm!=='granted')throw Error('Az értesítések engedélyezése szükséges.');const reg=await navigator.serviceWorker.ready;const keyResponse=await fetch(pushURL()+'/api/public-key');if(!keyResponse.ok)throw Error('A push szerver nem érhető el.');const {publicKey}=await keyResponse.json();let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(publicKey)});await pushRequest('/api/subscribe',{subscription:sub.toJSON(),timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone,reminder:state.settings.reminder,enabled:true});state.settings.reminderEnabled=true;save();render();toast('Háttér push engedélyezve!')}catch(err){toast(err.message||'Nem sikerült a push bekapcsolása')}}
async function disablePush(){try{const sub=await pushSubscription();if(sub){if(pushURL())await pushRequest('/api/unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe()}state.settings.reminderEnabled=false;save();render();toast('Push kikapcsolva')}catch(e){toast('Nem sikerült: '+e.message)}}
async function testPush(){try{const sub=await pushSubscription();if(!sub||!pushURL())throw Error('Előbb kapcsold be a háttér push-t.');await pushRequest('/api/test',{endpoint:sub.endpoint});toast('Teszt push elküldve')}catch(e){toast(e.message)}}
